use core.files as files
use core.process as process
use core.text as text

struct Report {
    count: Int
    name: String
    note: String
}

fn digit_value(ch: Char) Int -> {
    if ch == '0' -> return 0
    if ch == '1' -> return 1
    if ch == '2' -> return 2
    if ch == '3' -> return 3
    if ch == '4' -> return 4
    if ch == '5' -> return 5
    if ch == '6' -> return 6
    if ch == '7' -> return 7
    if ch == '8' -> return 8
    if ch == '9' -> return 9
    return -1
}

fn parse_count(value: String) Int -> {
    if value.is_empty() -> panic("missing count")
    result := 0
    loop ch in value.chars() {
        digit :: digit_value(ch)
        if digit < 0 -> panic("invalid count")
        result = result * 10 + digit
    }
    return result
}

fn escape_json(value: String) String -> {
    escaped := ""
    loop ch in value.chars() {
        if ch == '"' -> escaped += "\\\""
        else if ch == '\\' -> escaped += "\\\\"
        else if ch == '\n' -> escaped += "\\n"
        else if ch == '\t' -> escaped += "\\t"
        else -> escaped += "{ch}"
    }
    return escaped
}

fn run() {
    path :: process.argv().get(1) ?? panic("missing path")
    content :: files.read(path) ?? panic("read failed")
    count_text := ""
    name := ""
    note := ""
    seen_count := false
    seen_name := false
    seen_note := false

    loop raw in content.lines() {
        parts :: text.splitn(raw, "\t", 2)
        key :: parts.get(0) ?? panic("malformed field")
        value :: parts.get(1) ?? panic("malformed field")
        if key == "count" {
            if seen_count -> panic("duplicate count")
            count_text = value
            seen_count = true
        } else if key == "name" {
            if seen_name -> panic("duplicate name")
            name = value
            seen_name = true
        } else if key == "note" {
            if seen_note -> panic("duplicate note")
            note = value
            seen_note = true
        } else {
            panic("unknown field {key}")
        }
    }

    if !seen_count -> panic("missing count")
    if !seen_name -> panic("missing name")
    if !seen_note -> panic("missing note")
    report :: Report{count: parse_count(count_text), name: name, note: note}
    output :: "{{\"count\":{report.count},\"name\":\"{escape_json(report.name)}\",\"note\":\"{escape_json(report.note)}\"}}"
    print(output)
}
